import json
from dojo.simlab import paths
from dojo.simlab.gen_layouts import generate
for task in ('store_laptop_and_headphones','store_laptop_and_headphones_random'):
 root=paths.LAYOUTS/task
 for i in range(100050,100065):
  p=root/f'{i}.json'
  if p.exists():raise RuntimeError(f'refuse overwrite {p}')
  p.write_text(json.dumps(generate(task,i,variant=13,seed_salt='laptop-round2b-dense-2026-11-07-88c48b74'),indent=1))
  print(task,i,flush=True)
